 	defer p.Wait()

-	conc.ForEachIdxIn(p, input, f)
+	ForEachIdxIn(p, input, f)
 }

 func ForEach[T any](input []T, f func(*T)) {
 	p := New()
 	defer p.Wait()

-	conc.ForEachIdxIn(p, input, func(_ int, t *T) {
